INSERT OR IGNORE INTO products (slug, title, vendor, product_type, tags, description_html, price_amount, compare_at_amount, currency, available, status, published_at, updated_at) VALUES ('epson-tm-t20iii-thermal-usb', 'Epson TM-T20III Thermal - USB', 'eatOS - Restaurant management made simple', NULL, '[]', '<p><span>The TM-T20II is an affordable POS receipt printer with fast print speeds and economical features. The combination of its fast print speeds, high reliability and economical operation, make this Energy Star-qualified printer a must-have for small retail and specialty stores, hospitality venues and grocery stores.</span></p>', 169, NULL, 'USD', 1, 'published', '2021-08-25T04:02:07-04:00', '2026-08-29T07:43:11-04:00');
