INSERT OR IGNORE INTO products (slug, title, vendor, product_type, tags, description_html, price_amount, compare_at_amount, currency, available, status, published_at, updated_at) VALUES ('epson-tm-u220b-dot-matrix-lan', 'Epson TM-U220B - DOT Matrix - LAN', 'eatOS - Restaurant management made simple', NULL, '[]', '<p><span>The TM-U220 printers are designed to be compatible with existing systems built around a TM-U210. These systems can be upgraded simply by dropping in a TM-U220. Moreover, since the external dimensions are nearly identical, there is no need to change the installation environment. The transition to the new model is as smooth as can be.</span></p>', 289, NULL, 'USD', 1, 'published', '2021-08-25T04:00:33-04:00', '2026-08-29T07:43:11-04:00');
